using Prometheus;

class Program
{
    static void Main()
    {
        var metricServer = new MetricServer(port: 9090);
        metricServer.Start();

        var requestCounter = Metrics.CreateCounter("app_requests_total", "Total number of requests.");
        var requestDuration = Metrics.CreateHistogram("app_request_duration_seconds", "Request duration in seconds.",
            new HistogramConfiguration { Buckets = Histogram.ExponentialBuckets(0.01, 2, 10) });

        for (int i = 0; i < 5; i++)
        {
            requestCounter.Inc();
            using (requestDuration.NewTimer())
            {
                Thread.Sleep(50);
            }
        }

        Console.WriteLine("Metrics exposed at http://localhost:9090/metrics");
        Thread.Sleep(Timeout.Infinite);
    }
}
